import{_ as i,c as t,o as n,ae as o}from"./chunks/framework.DMK_uHmU.js";const d=JSON.parse('{"title":"AI Assistant User Guide","description":"","frontmatter":{},"headers":[],"relativePath":"Assistant/assistant-overview.md","filePath":"Assistant/assistant-overview.md"}'),a={name:"Assistant/assistant-overview.md"};function s(l,e,r,c,h,u){return n(),t("div",null,e[0]||(e[0]=[o('<h1 id="ai-assistant-user-guide" tabindex="-1">AI Assistant User Guide <a class="header-anchor" href="#ai-assistant-user-guide" aria-label="Permalink to &quot;AI Assistant User Guide&quot;">​</a></h1><h2 id="table-of-contents" tabindex="-1">Table of Contents <a class="header-anchor" href="#table-of-contents" aria-label="Permalink to &quot;Table of Contents&quot;">​</a></h2><ul><li><a href="#ai-assistant-user-guide">AI Assistant User Guide</a><ul><li><a href="#table-of-contents">Table of Contents</a></li><li><a href="#introduction">Introduction</a></li><li><a href="#getting-started">Getting Started</a><ul><li><a href="#accessing-the-assistant">Accessing the Assistant</a></li><li><a href="#first-interaction">First Interaction</a></li></ul></li><li><a href="#interface-overview">Interface Overview</a></li><li><a href="#conversation-basics">Conversation Basics</a><ul><li><a href="#asking-questions">Asking Questions</a></li><li><a href="#viewing-responses">Viewing Responses</a></li><li><a href="#using-the-microphone">Using the Microphone</a></li><li><a href="#attaching-files">Attaching Files</a></li></ul></li><li><a href="#blueprint-feature">Blueprint Feature</a><ul><li><a href="#selecting-blueprints">Selecting Blueprints</a></li><li><a href="#blueprint-home-screen">Blueprint Home Screen</a></li><li><a href="#conversation-starters">Conversation Starters</a></li></ul></li><li><a href="#working-with-responses">Working with Responses</a><ul><li><a href="#citations">Citations</a></li><li><a href="#viewing-referenced-content">Viewing Referenced Content</a></li><li><a href="#text-selection-actions">Text Selection Actions</a></li><li><a href="#response-actions">Response Actions</a></li></ul></li><li><a href="#advanced-features">Advanced Features</a><ul><li><a href="#chat-history">Chat History</a></li><li><a href="#content-panel">Content Panel</a></li><li><a href="#ai-settings">AI Settings</a></li><li><a href="#keyboard-shortcuts">Keyboard Shortcuts</a></li></ul></li><li><a href="#mobile-experience">Mobile Experience</a></li><li><a href="#troubleshooting">Troubleshooting</a></li></ul></li></ul><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>The AI Assistant is an advanced conversational interface that provides intelligent responses to your questions using large language models, knowledge bases, and content integration. This guide explains how to use the AI Assistant effectively, including its core features, navigation, and advanced capabilities.</p><h2 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h2><h3 id="accessing-the-assistant" tabindex="-1">Accessing the Assistant <a class="header-anchor" href="#accessing-the-assistant" aria-label="Permalink to &quot;Accessing the Assistant&quot;">​</a></h3><p>The AI Assistant is available from the main navigation menu. When you first access the Assistant, you&#39;ll see either:</p><ul><li>The LaunchPad screen with quick access to common resources and Blueprints</li><li>A welcome message inviting you to start a conversation</li></ul><h3 id="first-interaction" tabindex="-1">First Interaction <a class="header-anchor" href="#first-interaction" aria-label="Permalink to &quot;First Interaction&quot;">​</a></h3><p>To begin using the Assistant:</p><ol><li>Type a question in the prompt field at the bottom of the screen</li><li>Press Enter or click the Send button (paper airplane icon)</li><li>The AI will process your question and provide a response</li></ol><h2 id="interface-overview" tabindex="-1">Interface Overview <a class="header-anchor" href="#interface-overview" aria-label="Permalink to &quot;Interface Overview&quot;">​</a></h2><p>The AI Assistant interface consists of these major components:</p><ol><li><strong>Header Bar</strong>: Contains the home button, Blueprint selector, and utility controls</li><li><strong>Conversation Area</strong>: The main section where your conversation with the AI appears</li><li><strong>Prompt Field</strong>: The input area at the bottom where you type your questions</li><li><strong>Side Panel</strong>: Optional panel for chat history, content selection, or AI settings</li><li><strong>Action Menu</strong>: Available through the &quot;+&quot; button beside the prompt field</li></ol><h2 id="conversation-basics" tabindex="-1">Conversation Basics <a class="header-anchor" href="#conversation-basics" aria-label="Permalink to &quot;Conversation Basics&quot;">​</a></h2><h3 id="asking-questions" tabindex="-1">Asking Questions <a class="header-anchor" href="#asking-questions" aria-label="Permalink to &quot;Asking Questions&quot;">​</a></h3><p>To ask the AI a question:</p><ol><li>Type your question in the prompt field at the bottom of the screen</li><li>Press Enter or click the Send button (paper airplane icon)</li><li>Your question will appear in the conversation area</li><li>The AI will generate a response which appears below your question</li></ol><p>Tips for effective questions:</p><ul><li>Be specific about what you need</li><li>Provide relevant context</li><li>Ask one question at a time for best results</li><li>Use follow-up questions to refine or expand on earlier responses</li></ul><h3 id="viewing-responses" tabindex="-1">Viewing Responses <a class="header-anchor" href="#viewing-responses" aria-label="Permalink to &quot;Viewing Responses&quot;">​</a></h3><p>AI responses appear in the conversation area with:</p><ul><li>The AI&#39;s avatar icon (determined by the active Blueprint)</li><li>The response text with formatting (headings, lists, etc.)</li><li>Citations and references where applicable</li><li>Action buttons for response management</li></ul><p>During response generation:</p><ul><li>A &quot;Generating your response&quot; indicator appears</li><li>Text is streamed in real-time as it&#39;s generated</li><li>You can stop generation with the stop button (square icon)</li><li>Citations may be gathered after the main response is complete</li></ul><h3 id="using-the-microphone" tabindex="-1">Using the Microphone <a class="header-anchor" href="#using-the-microphone" aria-label="Permalink to &quot;Using the Microphone&quot;">​</a></h3><p>Instead of typing, you can use voice input:</p><ol><li>Click the microphone icon next to the prompt field</li><li>Begin speaking clearly</li><li>The system will transcribe your speech in real-time</li><li>When you stop speaking, the question will be submitted automatically</li><li>To cancel voice input, click the microphone icon again</li></ol><h3 id="attaching-files" tabindex="-1">Attaching Files <a class="header-anchor" href="#attaching-files" aria-label="Permalink to &quot;Attaching Files&quot;">​</a></h3><p>You can attach files to provide context for your questions:</p><ol><li>Click the paperclip icon in the prompt field</li><li>Select one or more files from your device (up to 10MB total)</li><li>Supported file types include PDFs, Word documents, Excel files, text files, and images</li><li>The files will appear as chips below the prompt field</li><li>Type your question about the files and send</li><li>The AI will process the files and use their content to inform its response</li></ol><h2 id="blueprint-feature" tabindex="-1">Blueprint Feature <a class="header-anchor" href="#blueprint-feature" aria-label="Permalink to &quot;Blueprint Feature&quot;">​</a></h2><h3 id="selecting-blueprints" tabindex="-1">Selecting Blueprints <a class="header-anchor" href="#selecting-blueprints" aria-label="Permalink to &quot;Selecting Blueprints&quot;">​</a></h3><p>Blueprints are specialized AI configurations for different purposes:</p><ol><li>Click the Blueprint selector in the header (shows current Blueprint name)</li><li>Choose from available Blueprints in the dropdown menu</li><li>Each Blueprint has specific knowledge, capabilities, and conversation starters</li><li>The AI avatar will change to match the selected Blueprint</li><li>You can also click a Blueprint avatar in previous responses to switch to that Blueprint</li></ol><h3 id="blueprint-home-screen" tabindex="-1">Blueprint Home Screen <a class="header-anchor" href="#blueprint-home-screen" aria-label="Permalink to &quot;Blueprint Home Screen&quot;">​</a></h3><p>When you select a Blueprint, you may see a home screen with:</p><ol><li>Blueprint name and description</li><li>Blueprint avatar/initials</li><li>Available conversation starters (if configured)</li><li>Option to start typing or use the microphone</li></ol><p>This screen helps you understand the Blueprint&#39;s purpose and available capabilities.</p><h3 id="conversation-starters" tabindex="-1">Conversation Starters <a class="header-anchor" href="#conversation-starters" aria-label="Permalink to &quot;Conversation Starters&quot;">​</a></h3><p>Many Blueprints include conversation starters - predefined prompts for common tasks:</p><ol><li>These appear on the Blueprint home screen</li><li>Click a conversation starter to immediately send that prompt</li><li>The AI will process the conversation starter as if you had typed it</li><li>You can also access conversation starters via the shortcuts menu (top right of conversation area)</li></ol><h2 id="working-with-responses" tabindex="-1">Working with Responses <a class="header-anchor" href="#working-with-responses" aria-label="Permalink to &quot;Working with Responses&quot;">​</a></h2><h3 id="citations" tabindex="-1">Citations <a class="header-anchor" href="#citations" aria-label="Permalink to &quot;Citations&quot;">​</a></h3><p>When the AI uses specific information sources, citations appear:</p><ol><li>Citations are numbered in the response text (e.g., [1], [2])</li><li>Click &quot;Citations&quot; at the bottom of the response to view sources</li><li>Each citation includes: <ul><li>Title of the source</li><li>Excerpt of the relevant content</li><li>Document type icon</li><li>Page number (if applicable)</li><li>Link to view the full source</li></ul></li></ol><p>You can:</p><ul><li>Expand individual citations to see excerpts</li><li>Click &quot;Expand All&quot; to view all citations at once</li><li>Click &quot;View&quot; to open referenced documents or web pages</li></ul><h3 id="viewing-referenced-content" tabindex="-1">Viewing Referenced Content <a class="header-anchor" href="#viewing-referenced-content" aria-label="Permalink to &quot;Viewing Referenced Content&quot;">​</a></h3><p>When viewing referenced content:</p><ol><li><p>For documents (PDF, Word, etc.):</p><ul><li>A full-screen viewer opens</li><li>The relevant excerpt is highlighted</li><li>You can navigate through the document</li><li>For PDFs, the specific page is shown</li></ul></li><li><p>For web pages:</p><ul><li>A new browser tab opens with the page</li><li>A &quot;Loading&quot; dialog briefly appears</li></ul></li><li><p>For videos:</p><ul><li>A video player opens with playback controls</li><li>Transcription may be available in an accordion below</li></ul></li></ol><h3 id="text-selection-actions" tabindex="-1">Text Selection Actions <a class="header-anchor" href="#text-selection-actions" aria-label="Permalink to &quot;Text Selection Actions&quot;">​</a></h3><p>When you select text in an AI response:</p><ol><li><p>A floating menu appears with options:</p><ul><li><strong>Reply</strong>: Uses the selected text as context for your next question</li><li><strong>Copy As</strong>: Copy text in regular or formatted form</li><li><strong>Send To</strong>: Send to Microsoft Word or a new email</li></ul></li><li><p>To use these options:</p><ul><li>Select the text you want to interact with</li><li>Choose the desired action from the floating menu</li><li>The action will be performed immediately</li></ul></li></ol><h3 id="response-actions" tabindex="-1">Response Actions <a class="header-anchor" href="#response-actions" aria-label="Permalink to &quot;Response Actions&quot;">​</a></h3><p>Each AI response has action buttons:</p><ol><li><strong>Replay Question</strong>: Copies the original question to the prompt field</li><li><strong>Copy Answer</strong>: Copies the entire response to your clipboard</li><li><strong>Modify Answer</strong>: Shows a menu of ways to change the response: <ul><li>Convert to step-by-step directions</li><li>Format data using tables</li><li>Elaborate on the answer</li><li>Summarize content</li><li>Translate to various languages</li><li>Change tone (Professional, Casual, Friendly, Marketing)</li><li>Change style (Business, Legal, Journalism, Creative)</li></ul></li><li><strong>Audio</strong>: Toggle speech synthesis to read the response aloud</li></ol><h2 id="advanced-features" tabindex="-1">Advanced Features <a class="header-anchor" href="#advanced-features" aria-label="Permalink to &quot;Advanced Features&quot;">​</a></h2><h3 id="chat-history" tabindex="-1">Chat History <a class="header-anchor" href="#chat-history" aria-label="Permalink to &quot;Chat History&quot;">​</a></h3><p>Access your conversation history through the side panel:</p><ol><li>Click the chat history icon in the header (document icon)</li><li>View a list of your past conversations</li><li>Click on any conversation to resume it</li><li>Use the New Chat button to start a fresh conversation</li><li>The three-dot menu for each conversation allows: <ul><li>Renaming the conversation</li><li>Adding tags</li><li>Deleting the conversation</li></ul></li></ol><h3 id="content-panel" tabindex="-1">Content Panel <a class="header-anchor" href="#content-panel" aria-label="Permalink to &quot;Content Panel&quot;">​</a></h3><p>The Content panel allows you to chat with specific documents:</p><ol><li>Select &quot;Content&quot; in the side panel menu</li><li>Browse available content or search for specific items</li><li>Select documents you want the AI to reference</li><li>Ask questions about the selected content</li><li>The AI will focus on the chosen documents when answering</li></ol><h3 id="ai-settings" tabindex="-1">AI Settings <a class="header-anchor" href="#ai-settings" aria-label="Permalink to &quot;AI Settings&quot;">​</a></h3><p>Customize the AI&#39;s behavior through Settings:</p><ol><li>Click the settings icon in the header or select &quot;Settings&quot; in the side panel</li><li>Adjust parameters such as: <ul><li>Model selection (Haiku or Sonnet)</li><li>Creativity level</li><li>Web search settings</li><li>Citation preferences</li><li>Knowledge base selection</li><li>Web pages to reference</li></ul></li><li>Changes apply to the current session only unless saved as a Blueprint</li></ol><h3 id="keyboard-shortcuts" tabindex="-1">Keyboard Shortcuts <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to &quot;Keyboard Shortcuts&quot;">​</a></h3><p>Keyboard shortcuts for power users:</p><ul><li><strong>Ctrl + N</strong>: Start new chat</li><li><strong>Ctrl + K</strong>: New chat keeping current settings</li><li><strong>Ctrl + E</strong>: Clear current conversation</li><li><strong>Ctrl + R</strong>: Rename current chat</li><li><strong>Ctrl + D</strong>: Delete current chat</li><li><strong>Ctrl + S</strong>: Show chat settings</li><li><strong>Ctrl + A</strong>: Attach file</li><li><strong>Ctrl + C</strong>: Switch to content panel</li></ul><h2 id="mobile-experience" tabindex="-1">Mobile Experience <a class="header-anchor" href="#mobile-experience" aria-label="Permalink to &quot;Mobile Experience&quot;">​</a></h2><p>When using the Assistant on mobile devices:</p><ol><li>The interface adapts to the smaller screen</li><li>Side panels become full-screen overlays</li><li>Access the menu by tapping the three-line icon</li><li>Scroll through responses by swiping</li><li>Long-press text to bring up the selection menu</li><li>Tap the microphone for voice input</li></ol><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p><strong>Issue</strong>: AI response stops generating</p><ul><li>Click the refresh button to retry</li><li>Check your network connection</li><li>Try starting a new conversation</li></ul><p><strong>Issue</strong>: Attached files not being processed</p><ul><li>Ensure file format is supported</li><li>Check that file size is under 10MB</li><li>Try with a smaller or different file format</li></ul><p><strong>Issue</strong>: Citations not appearing</p><ul><li>Some responses may not require citations</li><li>Check if &quot;Cite Sources&quot; is enabled in settings</li><li>Try asking more specific questions about documents</li></ul><p><strong>Issue</strong>: Voice input not working</p><ul><li>Check microphone permissions in your browser</li><li>Speak clearly and at a moderate pace</li><li>Try using shorter phrases</li></ul><p><strong>Issue</strong>: Response not relevant to my question</p><ul><li>Try rephrasing your question for clarity</li><li>Provide more specific context</li><li>Ask follow-up questions to guide the AI</li><li>Check which Blueprint is active</li><li>In settings, verify knowledge bases are correctly selected</li></ul><p><strong>Issue</strong>: Unable to find past conversations</p><ul><li>Check you&#39;re signed in with the correct account</li><li>Use the search function in chat history</li><li>Filter by tags if you&#39;ve applied them</li><li>Some older conversations may have been automatically archived</li></ul><hr><p>For additional assistance, contact your system administrator or support team.</p>',89)]))}const g=i(a,[["render",s]]);export{d as __pageData,g as default};
